// The FilterSet as a Sieve script (RFC 5228 and extensions Stalwart 0.16.25
// supports; corpus/wiki/gmail-on-jmap.md). The layout, which ./parse reads back:
//
//   # Generated by Postern. Edits here are overwritten.
//   # Postern filters, format 1
//   require [...];
//
//   # State                                (variables, declared at the top level)
//   set "postern_dollar" "$";              (only when a string needs a literal "${")
//   set "postern_skip" ""; ...             (only when there are filters)
//
//   # Blocked senders                      (only when there are any)
//   if address :is "from" [...] { fileinto :flags "$junk" :specialuse "\\Junk" "Junk Mail"; stop; }
//
//   # Filter 1                             (one per filter, in order)
//   if allof (<criteria>) { addflag ...; set "postern_..." "1"; }
//
//   # Delivery                             (only when there are filters)
//   delete -> Trash and stop; spam (unless "never send to Spam") -> keep and stop;
//   labels; forwards; then Inbox, All Mail or nothing (the implicit keep).
//
//   include :personal :optional "<name>";  (scripts Postern did not write)
//
// Filters only set flags and variables; the delivery part acts once, after
// every filter has run. So Spam wins over a label unless a matching filter
// says "never send to Spam" (Gmail's rule), spam is never forwarded, and every
// fileinto carries every filter's flags. Stalwart files a message into Spam
// itself only when the script leaves it in the Inbox alone (the implicit or
// an explicit keep): an explicit fileinto overrides its verdict
// (crates/email/src/sieve/ingest.rs `is_spam: ... && !did_file_into`).

import { DOLLAR_VARIABLE, quoteSieve } from "./escape.js";
import { GENERATED_MARKER, SCRIPT_FORMAT, type MailFilter, type FilterCriteria, type FilterSet } from "./model.js";

/** Fallback names for the system labels, should the server lack the special-use mailbox (Stalwart's defaults). */
export const FALLBACK_NAMES = { junk: "Junk Mail", trash: "Deleted Items", archive: "Archive", inbox: "INBOX" } as const;

/** The spam verdict Stalwart acts on: 50 % or more (crates/email/src/message/delivery.rs `is_spam`). */
export const SPAM_PERCENT = 50;

export const VAR = {
  skip: "postern_skip",
  nospam: "postern_nospam",
  delete: "postern_delete",
  filed: "postern_filed",
  label: (n: number) => `postern_label_${n}`,
  forward: (n: number) => `postern_forward_${n}`,
} as const;

/** Capabilities in the order `require` lists them. */
const CAPABILITY_ORDER = [
  "fileinto",
  "mailbox",
  "mailboxid",
  "special-use",
  "imap4flags",
  "variables",
  "body",
  "mime",
  "relational",
  "comparator-i;ascii-numeric",
  "spamtest",
  "spamtestplus",
  "copy",
  "encoded-character",
  "include",
] as const;
type CapabilityName = (typeof CAPABILITY_ORDER)[number];

class Writer {
  readonly lines: string[] = [];
  readonly caps = new Set<CapabilityName>();
  /** Some string needs "${postern_dollar}". */
  dollar = false;

  need(...caps: CapabilityName[]): void {
    for (const c of caps) this.caps.add(c);
  }

  /** A person's text, quoted. */
  str(value: string): string {
    const q = quoteSieve(value);
    if (q.encoded) this.need("encoded-character");
    if (q.dollar) {
      this.dollar = true;
      this.need("variables");
    }
    return q.text;
  }

  /** A string list `["a", "b"]`. */
  list(values: readonly string[]): string {
    return `[${values.map((v) => this.str(v)).join(", ")}]`;
  }

  line(text = ""): void {
    this.lines.push(text);
  }
}

/** Is-the-variable-set test (`string :is "${name}" "1"`). */
function isSet(name: string): string {
  return `string :is "\${${name}}" "1"`;
}

function criteriaTests(w: Writer, c: FilterCriteria): string[] {
  const tests: string[] = [];
  if (c.from.length > 0) tests.push(`header :contains "from" ${w.list(c.from)}`);
  if (c.to.length > 0) tests.push(`header :contains ["to", "cc"] ${w.list(c.to)}`);
  if (c.subject !== "") tests.push(`header :contains "subject" ${w.str(c.subject)}`);
  for (const word of c.words) {
    w.need("body");
    const q = w.str(word);
    tests.push(`anyof (header :contains "subject" ${q}, body :text :contains ${q})`);
  }
  if (c.notWords.length > 0) {
    w.need("body");
    const l = w.list(c.notWords);
    tests.push(`not anyof (header :contains "subject" ${l}, body :text :contains ${l})`);
  }
  if (c.hasAttachment) {
    w.need("mime");
    tests.push(`header :mime :anychild :contains "content-disposition" "attachment"`);
  }
  if (c.size) {
    tests.push(`size ${c.size.comparison === "larger" ? ":over" : ":under"} ${c.size.amount}${c.size.unit === "B" ? "" : c.size.unit}`);
  }
  return tests;
}

function writeFilter(w: Writer, filter: MailFilter, n: number): void {
  const tests = criteriaTests(w, filter.criteria);
  const a = filter.actions;
  w.line(`# Filter ${n}`);
  w.line(`if allof (${tests.join(", ")}) {`);
  if (a.markRead) {
    w.need("imap4flags");
    w.line(`  addflag "\\\\Seen";`);
  }
  if (a.star) {
    w.need("imap4flags");
    w.line(`  addflag "\\\\Flagged";`);
  }
  if (a.archive) w.line(`  set "${VAR.skip}" "1";`);
  if (a.label) w.line(`  set "${VAR.label(n)}" "1";`);
  if (a.forwardTo !== null) w.line(`  set "${VAR.forward(n)}" "1";`);
  if (a.delete) w.line(`  set "${VAR.delete}" "1";`);
  if (a.neverSpam) w.line(`  set "${VAR.nospam}" "1";`);
  w.line(`}`);
}

function writeDelivery(w: Writer, set: FilterSet): void {
  const filters = set.filters;
  const any = (pick: (f: MailFilter) => boolean) => filters.some(pick);
  w.line(`# Delivery`);
  if (any((f) => f.actions.delete)) {
    w.need("fileinto", "special-use");
    w.line(`if ${isSet(VAR.delete)} {`);
    w.line(`  fileinto :specialuse "\\\\Trash" ${w.str(FALLBACK_NAMES.trash)};`);
    w.line(`  stop;`);
    w.line(`}`);
  }
  // Spam stays in Spam (Stalwart files a kept message there) unless a filter says otherwise.
  w.need("spamtest", "spamtestplus", "relational", "comparator-i;ascii-numeric");
  w.line(`if allof (not ${isSet(VAR.nospam)}, spamtest :percent :value "ge" :comparator "i;ascii-numeric" "${SPAM_PERCENT}") {`);
  w.line(`  keep;`);
  w.line(`  stop;`);
  w.line(`}`);
  filters.forEach((f, i) => {
    const n = i + 1;
    if (f.actions.label) {
      w.need("fileinto", "mailbox", "mailboxid");
      w.line(`if ${isSet(VAR.label(n))} {`);
      w.line(`  fileinto :mailboxid ${w.str(f.actions.label.id)} ${w.str(f.actions.label.name)};`);
      w.line(`  set "${VAR.filed}" "1";`);
      w.line(`}`);
    }
  });
  filters.forEach((f, i) => {
    const n = i + 1;
    if (f.actions.forwardTo !== null) {
      w.need("copy");
      w.line(`if ${isSet(VAR.forward(n))} {`);
      w.line(`  redirect :copy ${w.str(f.actions.forwardTo)};`);
      w.line(`}`);
    }
  });
  // Where the message ends up besides its labels: skip the Inbox (All Mail when
  // no label took it), the Inbox in spite of a spam verdict, the Inbox next to
  // a label (a fileinto cancels the implicit keep), or nothing said at all.
  w.need("fileinto", "special-use");
  w.line(`if ${isSet(VAR.skip)} {`);
  w.line(`  if not ${isSet(VAR.filed)} {`);
  w.line(`    fileinto :specialuse "\\\\Archive" ${w.str(FALLBACK_NAMES.archive)};`);
  w.line(`  }`);
  w.line(`} elsif ${isSet(VAR.nospam)} {`);
  w.line(`  fileinto :specialuse "\\\\Inbox" ${w.str(FALLBACK_NAMES.inbox)};`);
  w.line(`} elsif ${isSet(VAR.filed)} {`);
  w.line(`  keep;`);
  w.line(`}`);
}

/** The variables the filters and the delivery part share, declared at the top level. */
export function stateVariables(set: FilterSet): string[] {
  const names: string[] = [VAR.skip, VAR.nospam, VAR.delete, VAR.filed];
  set.filters.forEach((f, i) => {
    if (f.actions.label) names.push(VAR.label(i + 1));
    if (f.actions.forwardTo !== null) names.push(VAR.forward(i + 1));
  });
  return names;
}

/**
 * The script for a filter set. Deterministic: the same set always gives the
 * same text. The set should be normalised (normalizeFilterSet) and every
 * filter valid (filterProblems empty); the generator does not check.
 */
export function generateSieve(set: FilterSet): string {
  const w = new Writer();
  const body = new Writer();
  // Body first, so the capabilities and variables it needs are known for the head.
  if (set.blocked.length > 0) {
    body.need("fileinto", "imap4flags", "special-use");
    body.line(`# Blocked senders`);
    body.line(`if address :is "from" ${body.list(set.blocked)} {`);
    body.line(`  fileinto :flags "$junk" :specialuse "\\\\Junk" ${body.str(FALLBACK_NAMES.junk)};`);
    body.line(`  stop;`);
    body.line(`}`);
    body.line();
  }
  if (set.filters.length > 0) {
    body.need("variables");
    set.filters.forEach((f, i) => {
      writeFilter(body, f, i + 1);
      body.line();
    });
    writeDelivery(body, set);
    body.line();
  }
  if (set.includes.length > 0) {
    body.need("include");
    body.line(`# Your own scripts, after Postern's filters`);
    for (const name of set.includes) body.line(`include :personal :optional ${body.str(name)};`);
    body.line();
  }

  // Stalwart's compiler scopes a variable to the block of its first `set`
  // (sieve-rs 0.7.3 register_local_var), so a flag set inside a filter's
  // block would read as "" in the delivery part. Declared at the top level,
  // before any use, every rule shares them.
  const state: string[] = [];
  if (body.dollar) state.push(`set "${DOLLAR_VARIABLE}" "$";`);
  if (set.filters.length > 0) for (const name of stateVariables(set)) state.push(`set "${name}" "";`);

  w.line(GENERATED_MARKER);
  w.line(`# Postern filters, format ${SCRIPT_FORMAT}`);
  const caps = CAPABILITY_ORDER.filter((c) => body.caps.has(c));
  if (caps.length > 0) w.line(`require [${caps.map((c) => `"${c}"`).join(", ")}];`);
  w.line();
  if (state.length > 0) {
    w.line(`# State`);
    for (const line of state) w.line(line);
    w.line();
  }
  return [...w.lines, ...body.lines].join("\r\n").replace(/(\r\n)+$/, "") + "\r\n";
}
